for f, pairs in P.items():
    p = os.path.join(root, 'tools', f); s = open(p, encoding='utf-8').read()
    for old, new in pairs:
        if old == new or (new in s and old not in s): continue
        assert s.count(old) == 1, (f, old[:80], s.count(old)); s = s.replace(old, new, 1)
    open(p, 'w', encoding='utf-8').write(s)
print('смоуки Х22.3в/г застосовано:', ', '.join(P))
